    typed_payload = sanitize_and_typecheck(action_intent, untrusted_context)

    # 3. Martech has no rollback (sent emails/spent cash are final), so shadow-execute first
    simulated_impact = vendor_api_dry_run(typed_payload, ephemeral_creds)

    # 4. Escalate only high-impact state diffs, avoiding human rubber-stamp fatigue on routine ops
    if simulated_impact.risk_score > agent_trust_threshold(agent_id):
        return route_to_canary_queue(typed_payload, simulated_impact)

    # 5. Execute via vendor proxy that embeds agent UUID + prompt hash into vendor metadata/tags
    return gateway.dispatch_with_provenance(typed_payload, ephemeral_creds, provenance_id=hash(untrusted_context))

